          intent: { type: 'string', enum: ['sell', 'let'], description: 'sell, or let (rent it out)' },
          address: { type: 'string', description: 'Street and number of the property' },
          city: { type: 'string' },
          district: { type: 'string' },
          property_type: { type: 'string', enum: ['apartment', 'house', 'plot', 'commercial', 'other'] },
          area_m2: { type: 'number', description: 'Floor area in square metres' },
          rooms: { type: 'integer' },
