    {
      name: 'escalate_to_human',
      description: 'Hand this conversation off to a human team member, who is alerted immediately with your summary and the whole conversation. Call this when the visitor explicitly asks for a human, seems angry or frustrated, raises a legal or refund-related issue, shares something sensitive you should not handle alone, asks something you genuinely cannot answer even after searching the knowledge base, asks you to do something outside what you are permitted to do, or whenever you tell the visitor a team member will contact them, send them something or follow up. Continue the conversation naturally after calling this -- let the visitor know a team member will follow up, without mentioning this tool or any internal process.',
      input_schema: {
        type: 'object',
        properties: {
          reason: { type: 'string', enum: ['low_confidence', 'customer_requested_human', 'angry_customer', 'legal_issue', 'refund_requested', 'sensitive_info', 'no_trusted_source', 'action_exceeds_permissions', 'other'], description: 'Which of these best matches why a human is needed' },
          priority: { type: 'string', enum: ['low', 'normal', 'high', 'urgent'], description: 'How urgently a human should look at this -- urgent for anything time-sensitive or an upset customer, high for legal/refund issues, normal otherwise' },
          context_summary: { type: 'string', description: 'A concise summary of the conversation and why a human is needed, written for a team member with zero prior context' }
        },
        required: ['reason', 'context_summary']
      }
    },
    {
      name: 'change_viewing',
      description: 'Confirm, move or cancel one of the client\'s own upcoming bookings (listed under UPCOMING VIEWINGS with their appointment_id). confirm = they say they are coming. reschedule = they agreed a new time that check_availability returned. cancel = they clearly asked to cancel. Only for their own bookings; the team and the calendar are updated automatically.',
      input_schema: {
        type: 'object',
        properties: {
          appointment_id: { type: 'string', description: 'The appointment_id from UPCOMING VIEWINGS' },
          action: { type: 'string', enum: ['confirm', 'reschedule', 'cancel'] },
          new_starts_at: { type: 'string', description: 'For reschedule: ISO 8601 start, exactly as returned by check_availability' },
          new_ends_at: { type: 'string', description: 'For reschedule: ISO 8601 end, exactly as returned by check_availability' },
          reason: { type: 'string', description: 'For cancel or reschedule: the reason, if they gave one' }
        },
        required: ['appointment_id', 'action']
      }
    }
  ]))
}) }}

