// Extract the tool_use block from the latest Claude response.
// Guardrails (Claude proposes, this node decides):
//  1. Only allow-listed tools are executed; anything else is denied.
//  2. The agency's own rule for bookings (Settings -> What Elliot may do on its
//     own). When bookings need approval, Elliot does NOT book: the request goes
//     to the team as a hand-over, and Claude is told to say it's requested, not
//     confirmed. Claude can't talk its way round this: the decision is made
//     here, from the agency's saved settings.
const resp = $json;
const toolBlock = (resp.content || []).find(b => b.type === 'tool_use');
if (!toolBlock) { throw new Error('Expected tool_use block but none found'); }

const ALLOWED_TOOLS = ['search_company_knowledge', 'capture_lead', 'check_availability', 'book_appointment', 'escalate_to_human', 'search_listings', 'change_viewing', 'record_valuation_request'];
const input = toolBlock.input && typeof toolBlock.input === 'object' && !Array.isArray(toolBlock.input) ? toolBlock.input : {};
let decision = ALLOWED_TOOLS.includes(toolBlock.name) ? 'auto_approved' : 'denied_by_policy';

let rules = {};
try { rules = $('Load AI Config').first().json.autonomy_rules || {}; } catch (e) { rules = {}; }
if (typeof rules === 'string') { try { rules = JSON.parse(rules); } catch (e) { rules = {}; } }
let mode = 'agency';
try { mode = $('Merge Tenant Context').first().json.assistant_mode || 'agency'; } catch (e) { mode = 'agency'; }

let tool_name = toolBlock.name;
let tool_input = input;
let held_tool = null;
// getelliot.eu's own assistant (sales) books its calls directly.
if (decision === 'auto_approved' && tool_name === 'book_appointment' && mode !== 'sales'
    && rules && rules.book_appointment && rules.book_appointment.mode === 'approval_required') {
  held_tool = 'book_appointment';
  const what = input.kind === 'valuation' ? 'a valuation visit' : 'a viewing';
  tool_name = 'escalate_to_human';
  tool_input = {
    reason: 'action_exceeds_permissions',
    priority: 'high',
    context_summary: (`Booking request waiting for you: the client asked for ${what} from ${input.starts_at || '?'} to ${input.ends_at || '?'}` +
      (input.listing_id ? `, listing ${input.listing_id}` : '') +
      (input.property_address ? `, at ${input.property_address}` : '') +
      (input.notes ? `. Notes: ${input.notes}` : '') +
      '. Your agency confirms bookings itself (Settings): confirm this time with the client or propose another.').slice(0, 1500),
  };
}

return [{ json: {
  tool_name,
  tool_input,
  tool_use_id: toolBlock.id,
  decision,
  // What Claude asked for, and what the log should say about it.
  requested_tool: toolBlock.name,
  held_tool,
  log_decision: held_tool ? 'pending' : decision,
}}];

// Append this iteration's assistant tool_use turn + the tool_result to the
// running message history, then loop back to Assemble Request for another
// Claude call. Uses .item (loop-safe) so accumulation is correct across turns.
// Where a client can see a property: the agency's own page for it when it
// has one, otherwise Elliot's property page with the photos (/p/<id> on the
// dashboard; photos added in Listings or imported from Google Drive). A
// Google Drive / Dropbox folder isn't a property page, so it gets ours.
const DASHBOARD_URL = 'https://app.getelliot.eu'; // change if the dashboard moves to its own domain
function propertyLink(id, url) {
  const own = String(url || '').trim();
  if (/^https?:\/\//i.test(own) && !/drive\.google\.com|dropbox\.com/i.test(own)) return own;
  return id ? `${DASHBOARD_URL}/p/${id}` : null;
}

const state = $('Assemble Request').item.json;
const priorMessages = state.claude_messages;
const claudeResp = $('Call Claude').item.json;
const toolCall = $('Extract Tool Call').item.json;
const output = $input.first().json;

// 0048: the tool itself broke (a sub-workflow crashed: Google refused, a
// database error, a missing workflow). n8n hands back { error } instead of
// stopping, and Claude is told the truth so it never claims it was done.
// (record_valuation_request answers { error } for things Claude can fix, such as a
// missing contact; it has its own wording below.)
const toolCrashed = toolCall.tool_name !== 'record_valuation_request' && !!output && output.error !== undefined && output.error !== null
  && !['success', 'found', 'available_slots', 'results', 'result', 'reason', 'action', 'status'].some((k) => k in output);
const toolError = toolCrashed
  ? String(typeof output.error === 'string' ? output.error : (output.error.message || output.error.description || JSON.stringify(output.error))).slice(0, 400)
  : null;
const FAILED_TEXT = (name) => `TOOL FAILED: ${name} could not be completed because of a technical problem on our side. Nothing was done. ` +
  (name === 'escalate_to_human'
    ? 'The team has been alerted another way. Tell the client that someone from the team will contact them, and do not call escalate_to_human again.'
    : 'Do not say or imply it was done. Apologise in one short sentence, then call escalate_to_human (reason "other") with what the client wanted, so the team finishes it; tell the client the team will follow up. Do not call this tool again in this reply.');

let resultText;

if (toolCrashed) {
  resultText = FAILED_TEXT(toolCall.requested_tool || toolCall.tool_name);

} else if (toolCall.held_tool === 'book_appointment') {
  // 0047: this agency confirms bookings itself; the request went to the team.
  resultText = 'NOT BOOKED. This agency confirms every booking itself, so nothing was put in the calendar. ' +
    'The requested time has been passed to the team, who will confirm it with the client or propose another. ' +
    'Tell the client exactly that: the time is requested, not confirmed yet, and the team will be in touch shortly. ' +
    'Do not say it is booked, and do not call book_appointment again for this request.';

} else if (toolCall.tool_name === 'search_company_knowledge') {
  const results = output.results || [];
  resultText = output.found && results.length
    ? results.map(r => `[source: ${r.section_ref || r.document_id}] ${r.content}`).join('\n\n')
    : (output.message || 'No relevant results found in the knowledge base.');

} else if (toolCall.tool_name === 'check_availability') {
  const slots = output.available_slots || [];
  resultText = slots.length
    ? `Available slots (times in ${output.timezone || 'UTC'}):\n` +
      slots.map(s => `- ${s.starts_at} to ${s.ends_at}`).join('\n')
    : 'No available slots were found in that date range.';

} else if (toolCall.tool_name === 'book_appointment' && output.kind === 'consultation') {
  // getelliot.eu's own assistant booked a call (0037).
  resultText = output.success
    ? `Call booked: ${output.call_label || 'call'} from ${output.starts_at} to ${output.ends_at}.` +
      (output.meet_link ? ` Google Meet link: ${output.meet_link}.` : ' The Google Meet link will be in the calendar invitation.') +
      (output.confirmation_sent_to
        ? ` A confirmation email was sent to ${output.confirmation_sent_to}.`
        : output.confirmation_error
          ? ` The call IS booked, but the confirmation email couldn't be sent (${output.confirmation_error}). Give them the link here.`
          : ' No confirmation email was sent. Do not say one is coming.')
    : `Booking failed: ${output.error || 'That time is no longer free. Offer other times.'}`;

} else if (toolCall.tool_name === 'book_appointment') {
  resultText = output.success
    ? `${output.kind === 'valuation' ? `Valuation visit booked${output.location ? ` at ${output.location}` : ''}` : 'Appointment booked successfully'}. Appointment ID: ${output.appointment_id}, from ${output.starts_at} to ${output.ends_at}, status: ${output.status}.` +
      (output.agent_name ? ` Agent: ${output.agent_name}.` : '') +
      (output.listing_title ? ` Property: ${output.listing_title}${output.listing_address ? `, ${output.listing_address}` : ''}.` : '') +
      (output.listing_link ? ` Property link: ${output.listing_link}.` : '') +
      (output.confirmation_sent_to
        ? ` A confirmation email was sent to ${output.confirmation_sent_to}.`
        : output.confirmation_error
          ? ` The viewing IS booked, but the confirmation email to ${output.confirmation_to || 'the visitor'} could not be sent (${output.confirmation_error}). Tell the visitor the booking is confirmed here in the chat and that the email didn't go through.`
          : ' No confirmation email was sent (no email address on file). Do not say one is coming.')
    : `Booking failed: ${output.error || 'That time slot is no longer available. Please choose a different time.'}`;

} else if (toolCall.tool_name === 'change_viewing') {
  // 0038: the client confirmed, moved or cancelled one of their bookings (workflow 37).
  if (!output.success) {
    resultText = `Not done: ${output.error || 'the booking could not be changed'}. Tell the client plainly and offer what you can (other times, or a person from the team).`;
  } else if (output.action === 'confirm') {
    resultText = `Confirmed: the client is coming on ${output.when}. Thank them briefly.`;
  } else if (output.action === 'cancel') {
    resultText = `Cancelled the booking on ${output.when}. The team has been told and the calendar updated.` +
      (output.email_sent_to ? ` A cancellation email went to ${output.email_sent_to}.` : '') + ' Offer to book another time if it fits.';
  } else {
    resultText = `Moved: the booking is now ${output.when} (was ${output.previous_when}). The team has been told.` +
      (output.calendar === 'failed' ? ' (The calendar entry could not be updated; the team will fix it.)' : '') +
      (output.email_sent_to ? ` A confirmation of the new time went to ${output.email_sent_to}.` : ' No email was sent.');
  }

} else if (toolCall.tool_name === 'capture_lead') {
  resultText = output.success
    ? `Lead saved successfully. Status: ${output.status}, score: ${output.score}${output.contact_email ? `, contact: ${output.contact_email}` : ''}.`
    : `Failed to save lead information.`;

} else if (toolCall.tool_name === 'search_listings') {
  const r = output.result || {};
  const list = r.listings || [];
  const alternatives = r.alternatives || [];
  const fmt = (l) => [
    `- ${l.title}${l.reference ? ` (ref ${l.reference})` : ''}`,
    l.listing_id ? `  listing_id: ${l.listing_id} (pass this to book_appointment for a viewing; never show it to the visitor)` : null,
    `  ${l.transaction_type === 'rent' ? 'For rent' : 'For sale'}: ${l.price != null ? `${l.price} ${l.currency}${l.transaction_type === 'rent' ? '/month' : ''}` : 'price on request'}`,
    `  ${[l.address, l.district, l.city].filter(Boolean).join(', ')}${l.area_m2 ? `, ${l.area_m2} m2` : ''}${l.rooms ? `, ${l.rooms} rooms` : ''}${l.floor != null ? `, floor ${l.floor}` : ''}`,
    l.available_from ? `  Available from ${l.available_from} (not before)` : '  Available now',
    l.features && l.features.length ? `  Features: ${l.features.join(', ')}` : null,
    l.description ? `  ${l.description}` : null,
    propertyLink(l.listing_id, l.url) ? `  Link (send this to the visitor): ${propertyLink(l.listing_id, l.url)}` : null,
    l.photo_count ? `  Photos: ${l.photo_count} (on the link)` : '  No photos yet (the link still shows the details)',
  ].filter(Boolean).join('\n');
  if (list.length) {
    resultText = `${list.length} available listing(s) found:\n` + list.map(fmt).join('\n');
  } else if (alternatives.length) {
    resultText = 'No exact match for those filters. These are the closest available options -- show them now with their links, ' +
      'say honestly how each differs from what the visitor asked for (price, area, size) and why it could still suit them, ' +
      'and offer a viewing. Do not say the team will look for options instead:\n' + alternatives.map(fmt).join('\n');
  } else {
    resultText = 'No available listings match, and there is nothing close either. Do not invent any. Tell the visitor honestly, ' +
      'capture what they want with capture_lead, and offer to have the team contact them when something comes up (call escalate_to_human if they accept).';
  }

} else if (toolCall.tool_name === 'record_valuation_request') {
  // 0043: a seller or landlord.
  let r = output.result;
  if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) { r = null; } }
  resultText = r && r.lead_id
    ? `Saved: ${r.intent === 'let' ? 'landlord' : 'seller'} lead (${r.status}). Now: do not give any price or estimate. Offer a free valuation visit by an agent at their property: call check_availability, offer real times, then book_appointment with kind "valuation" and property_address. Call escalate_to_human with reason hot_lead and a short summary of the property and what they want.`
    : `Not saved (${(output.error && (output.error.message || output.error)) || 'unknown error'}). If you don't have their contact_id yet, call capture_lead with their name and phone or email first, then call record_valuation_request again.`;

} else if (toolCall.tool_name === 'escalate_to_human') {
  resultText = `Escalated to a human team member (reason: ${output.reason}, priority: ${output.priority}). Continue the conversation naturally -- let the visitor know someone will follow up, without mentioning this tool or any internal process.`;

} else {
  resultText = JSON.stringify(output);
}

const updatedMessages = [
  ...priorMessages,
  { role: 'assistant', content: claudeResp.content },
  { role: 'user', content: [{ type: 'tool_result', tool_use_id: toolCall.tool_use_id, content: resultText }] }
];

return [{ json: {
  tenant_id: state.tenant_id,
  tenant_name: state.tenant_name,
  tenant_industry: state.tenant_industry,
  conversation_id: state.conversation_id,
  system_prompt: state.system_prompt,
  claude_messages: updatedMessages,
  // 0048: for 'Tool Failed?' -> 'Record Tool Failure'
  tool_failed: toolCrashed,
  failed_tool: toolCall.requested_tool || toolCall.tool_name,
  tool_error: toolError,
  tool_turns: (state.tool_turns || 0) + 1,
  // input-equivalent: cache reads count 0.1x, cache writes 1.25x (prompt caching)
  usage_input_tokens: (state.usage_input_tokens || 0) + ((u) => u ? (u.input_tokens || 0) + Math.round((u.cache_read_input_tokens || 0) * 0.1) + Math.round((u.cache_creation_input_tokens || 0) * 1.25) : 0)(claudeResp.usage),
  usage_output_tokens: (state.usage_output_tokens || 0) + ((claudeResp.usage && claudeResp.usage.output_tokens) || 0)
} }];

// Append the lead-capture assistant tool_use turn + tool_result to the running
// message history, then loop back to Assemble Request for another Claude call.
const state = $('Assemble Request').item.json;
const priorMessages = state.claude_messages;
const claudeResp = $('Call Claude').item.json;
const toolCall = $('Extract Tool Call').item.json;

const leadResult = $input.first().json;
const output = leadResult;
// 0048: the tool itself broke (a sub-workflow crashed: Google refused, a
// database error, a missing workflow). n8n hands back { error } instead of
// stopping, and Claude is told the truth so it never claims it was done.
const toolCrashed = !!output && output.error !== undefined && output.error !== null
  && !['success', 'found', 'available_slots', 'results', 'result', 'reason', 'action', 'status'].some((k) => k in output);
const toolError = toolCrashed
  ? String(typeof output.error === 'string' ? output.error : (output.error.message || output.error.description || JSON.stringify(output.error))).slice(0, 400)
  : null;
const FAILED_TEXT = (name) => `TOOL FAILED: ${name} could not be completed because of a technical problem on our side. Nothing was done. ` +
  (name === 'escalate_to_human'
    ? 'The team has been alerted another way. Tell the client that someone from the team will contact them, and do not call escalate_to_human again.'
    : 'Do not say or imply it was done. Apologise in one short sentence, then call escalate_to_human (reason "other") with what the client wanted, so the team finishes it; tell the client the team will follow up. Do not call this tool again in this reply.');
let resultText;
if (toolCrashed) {
  // The client's details were NOT saved: the team must be told, or the lead is lost.
  resultText = 'TOOL FAILED: the client\'s details could not be saved because of a technical problem on our side. ' +
    'Call escalate_to_human (reason "other") now and put the client\'s name, phone, email and what they are looking for in the summary, so the team has them. ' +
    'Carry on the conversation normally; do not mention a problem. Do not call capture_lead again in this reply.';
} else if (leadResult.success) {
  resultText = `Lead captured successfully. Status: ${leadResult.status}.`;
  if (leadResult.contact_id) {
    resultText += ` The contact_id for this visitor is ${leadResult.contact_id} -- use this exact value as contact_id when calling book_appointment.`;
  } else {
    resultText += ` Note: no contact_id is available yet, so do not call book_appointment until a contact has been created.`;
  }
} else {
  resultText = 'There was a problem recording this lead information -- continue the conversation normally without mentioning this to the visitor.';
}

const updatedMessages = [
  ...priorMessages,
  { role: 'assistant', content: claudeResp.content },
  { role: 'user', content: [{ type: 'tool_result', tool_use_id: toolCall.tool_use_id, content: resultText }] }
];

return [{ json: {
  tenant_id: state.tenant_id,
  tenant_name: state.tenant_name,
  tenant_industry: state.tenant_industry,
  conversation_id: state.conversation_id,
  system_prompt: state.system_prompt,
  claude_messages: updatedMessages,
  tool_failed: toolCrashed,
  failed_tool: 'capture_lead',
  tool_error: toolError,
  tool_turns: (state.tool_turns || 0) + 1,
  usage_input_tokens: (state.usage_input_tokens || 0) + ((claudeResp.usage && claudeResp.usage.input_tokens) || 0),
  usage_output_tokens: (state.usage_output_tokens || 0) + ((claudeResp.usage && claudeResp.usage.output_tokens) || 0)
} }];

// Tool call was denied by policy (not on the allow-list). Do NOT execute it.
// Return a safe fallback message instead of the tool result.
return [{ json: { final_text: "I'm not able to do that directly, but I can pass this along to the team." } }];

// Extract the assistant's final plain-text reply. If Claude returned no text
// (e.g. hit the tool-turn cap while still requesting a tool), fall back to a
// graceful message so the visitor never receives an empty response.
const resp = $json;
const textBlock = (resp.content || []).find(b => b.type === 'text');
let finalText = textBlock ? textBlock.text : '';
if (!finalText || !finalText.trim()) {
  finalText = 'Thanks! A member of our team will follow up with you shortly to finalize the details.';
}
// Tokens for this whole reply: every earlier tool-loop call plus this last one.
const state = $('Assemble Request').item.json;
// input-equivalent: cache reads count 0.1x, cache writes 1.25x (prompt caching)
const usageInput = (state.usage_input_tokens || 0) + ((u) => u ? (u.input_tokens || 0) + Math.round((u.cache_read_input_tokens || 0) * 0.1) + Math.round((u.cache_creation_input_tokens || 0) * 1.25) : 0)(resp.usage);
const usageOutput = (state.usage_output_tokens || 0) + ((resp.usage && resp.usage.output_tokens) || 0);
// EU AI Act Art. 50(1): people must know they're talking to an AI from the
// first interaction. The website chat says so in its header; on WhatsApp and
// email, Elliot's first reply in a conversation opens with one line saying so,
// in the language of the reply.
try {
  const ctx = $('Merge Tenant Context').first().json;
  let history = [];
  try { history = $('Load Conversation History').all().map((r) => r.json); } catch (e) { history = []; }
  const answeredBefore = history.some((h) => h.role === 'assistant' || h.role === 'human_agent');
  if (!answeredBefore && (ctx.channel === 'whatsapp' || ctx.channel === 'email')) {
    const polish = /[ąćęłńóśźż]|\b(dzień dobry|dziękuj\w*|proszę|mieszkani\w*|prezentacj\w*|jest|są|nie|się|oraz)\b/i.test(finalText);
    const own = ctx.assistant_mode === 'sales';
    const agency = String(ctx.tenant_name || '').trim();
    const line = polish
      ? (own ? 'Tu Elliot, asystent AI. W każdej chwili mogą Państwo poprosić o rozmowę z człowiekiem.'
             : `Tu Elliot, asystent AI${agency ? ` biura ${agency}` : ''}. W każdej chwili mogą Państwo poprosić o kontakt z pracownikiem biura.`)
      : (own ? 'This is Elliot, an AI assistant. You can ask for a person at any time.'
             : `This is Elliot, the AI assistant${agency ? ` of ${agency}` : ''}. You can ask for someone from the team at any time.`);
    finalText = `${line}\n\n${finalText}`;
  }
} catch (e) { /* never block a reply over the notice */ }
return [{ json: { final_text: finalText, raw: resp, usage_input_tokens: usageInput, usage_output_tokens: usageOutput } }];

// "Thanks", "ok", "dziękuję", 👍 after Elliot's answer don't need Claude:
// a short reply in the same language costs nothing. Anything else -- or an
// "ok" that could be answering a question or a reminder -- goes to Claude.
const s = $input.first().json;
const history = $('Load Conversation History').all().map((r) => r.json);
const lastAssistant = [...history].reverse().find((h) => h.role === 'assistant' || h.role === 'human_agent');
const raw = String(s.message || '').trim();
const words = raw.toLowerCase()
  .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, ' ')
  .replace(/[!.,:;'"()\-]+/g, ' ')
  .replace(/\s+/g, ' ').trim();
const emojiOnly = raw.length > 0 && words === '';
const ACK_EN = new Set(['thanks', 'thank you', 'thanks a lot', 'thank you very much', 'many thanks', 'thx', 'ty', 'cheers',
  'ok', 'okay', 'ok thanks', 'okay thanks', 'ok thank you', 'okay thank you', 'great', 'great thanks', 'great thank you',
  'perfect', 'perfect thanks', 'perfect thank you', 'cool', 'cool thanks', 'super', 'awesome', 'got it', 'got it thanks', 'noted', 'brilliant']);
const ACK_PL = new Set(['dzięki', 'dzieki', 'dziękuję', 'dziekuje', 'dziękuje', 'dziekuję', 'dziękuję bardzo', 'bardzo dziękuję',
  'dzięki wielkie', 'wielkie dzięki', 'super dzięki', 'ok dzięki', 'ok dziękuję', 'okej', 'okej dzięki', 'dobrze', 'dobrze dziękuję',
  'świetnie', 'swietnie', 'świetnie dziękuję', 'jasne', 'jasne dzięki', 'rozumiem', 'rozumiem dziękuję', 'super dziękuję']);
const isAck = emojiOnly || ACK_EN.has(words) || ACK_PL.has(words);
const prev = lastAssistant ? String(lastAssistant.content || '') : '';
const safe = isAck && !!prev
  && !prev.includes('?')
  && !/remind|przypom|confirm|potwierd|reply to|odpowied/i.test(prev)
  && raw.length <= 40;
// Language: the thank-you itself, else Elliot's last message (Polish letters or common Polish words).
const POLISH = /[ąćęłńóśźż]|\b(jest|są|nie|się|dla|oraz|mieszkani\w*|prezentacj\w*|zarezerwowan\w*|termin\w*|proszę|dziękuj\w*|czwartek|piątek|jutro|dzisiaj)\b/i;
const polish = ACK_PL.has(words) || (!ACK_EN.has(words) && POLISH.test(prev));
const quick_reply = safe
  ? (polish ? 'Nie ma za co! Gdyby coś jeszcze było potrzebne, proszę śmiało pisać.'
            : "You're welcome! If anything else comes up, just write here.")
  : null;
return [{ json: { ...s, quick_reply } }];

