// identity can be trusted. The public /chat webhook never passes through here,
// and a caller can't set this field (it sits beside body, not inside it).
return $input.all().map((i) => ({ json: { ...i.json, internal: true } }));

// 0048: Claude couldn't be reached after three tries (overloaded, timed out,
// key or credit problem). The client must not be left without an answer and
// the team must know: a short holding reply in the client's language, an
// escalation, and a line in the audit log that the health alerts pick up.
const ctx = $('Merge Tenant Context').first().json;
let conversationId = null;
try { conversationId = $('Get or Create Conversation').first().json.conversation_id; } catch (e) { conversationId = null; }
const input = $input.first().json || {};
const err = input.error;
const detail = typeof err === 'string' ? err
  : (err && (err.message || err.description || (err.cause && err.cause.message))) || input.message || 'no response';
const polish = /[ąćęłńóśźż]|\b(dzień dobry|dziękuj\w*|proszę|mieszkani\w*|prezentacj\w*|czy|jest|są|nie|się|oraz)\b/i.test(String(ctx.message || ''));
const reply = polish
  ? 'Przepraszamy, w tej chwili nie mogę odpowiedzieć. Przekazałem wiadomość do zespołu i ktoś wkrótce się z Państwem skontaktuje.'
  : "Sorry, I can't answer right now. I've passed your message to the team and someone will get back to you shortly.";
return [{ json: {
  tenant_id: ctx.tenant_id,
  conversation_id: conversationId,
  channel: ctx.channel || 'chat_widget',
  error: ('Claude: ' + String(detail)).slice(0, 400),
  reply,
} }];

